"""Pure report renderer for baseline study receipts. Never edits or scores a dataset."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any


def build_baseline_report(receipt: Mapping[str, Any], *, source: str) -> str:
    fixture = receipt["conditions"]["validation_only"] or receipt["population"]["kind"] != "development"
    lines = [
        "# Baseline evaluation report",
        "",
        "Generated by apexpinn.eval.baseline_report. Do not edit by hand.",
        "",
        f"Source: `{source}`; counts, scores and elapsed times are `Observed` in that source.",
        f"G1: **{receipt['G1']}**.",
        "",
        "**CRAFTED/VALIDATION DATA ONLY. No strongest real-data baseline is established.**"
        if fixture
        else "Development outer-test results. Acceptance still requires review of the underlying evidence.",
        "",
        f"Source kind: {receipt['population']['kind']}; phi: {receipt['conditions']['phi']};",
        f"MLP steps per fit: {receipt['conditions']['mlp_steps']}; "
        f"final members: {receipt['conditions']['ensemble_members']}.",
        "Training offsets are profiled out; evaluation uses shared history-only anchoring "
        "and original-lap endpoints.",
        "Inner split: next configured circuit group; normalization refitted on inner training circuits only.",
        "Five final fits are timed separately and are not tuning trials. "
        "Failed trials count; no retries outside budget.",
        "B0/B2 have one declared configuration, using the finite-space exception. B1/B3 have 20 each.",
        "",
        "## Tuning and final training accounting",
        "",
        "| Outer fold | Model | Trials | Finished | Failed | Trial seconds | Final fits | Final seconds |",
        "| :--- | :--- | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    keys = sorted({(r["outer_fold"], r["model"]) for r in receipt["trials"]})
    for fold, name in keys:
        trials = [r for r in receipt["trials"] if r["outer_fold"] == fold and r["model"] == name]
        fits = [r for r in receipt["final_member_fits"] if r["fold"] == fold and r["model"] == name]
        finished = sum(r["status"] == "finished" for r in trials)
        lines.append(
            f"| {fold} | {name} | {len(trials)} | {finished} | {len(trials) - finished} | "
            f"{sum(r['elapsed_s'] for r in trials):.6g} | {len(fits)} | "
            f"{sum(r['elapsed_s'] for r in fits):.6g} |"
        )
    lines += [
        "",
        "Per-trial status, parameters, seed, error and perf_counter seconds are retained in JSON files.",
        "Trial clocks include construction, fit and inner scoring; preprocessing is outside the clock.",
        "Elapsed fit time is not inference latency or equal compute fairness.",
        "Execution v2 prepares immutable inputs once per fold/stage; shared preparation is timed separately.",
        "Inner selection computes primary-horizon RMSE; outer evaluation retains every declared horizon.",
        "Resumed legacy trial times retain their original construction/all-horizon clock scope and cannot be "
        "compared directly with replay-only trial times. Completed trials are never refitted on resume.",
        "Abandoned legacy final work is outside the selected final-fit totals; see resume provenance.",
        "",
        "## Scores by horizon",
        "",
        "Each horizon scores its endpoint. Scores retain all four evidence fields.",
        "",
        "| Model | Horizon | RMSE s | MAE s | CRPS s | Coverage 50 | Width 50 s | Coverage 90 | Width 90 s |",
        "| :--- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    groups = {}
    for metric in receipt["metrics"]:
        key = (metric["conditions"]["model"], metric["conditions"]["horizon_actual_laps"])
        groups.setdefault(key, {})[metric["quantity"]["metric"]] = metric["value"]
    for (name, horizon), values in sorted(groups.items()):
        cells = [
            "Unknown" if values.get(key) is None else f"{values[key]:.6g}"
            for key in ("rmse", "mae", "crps", "coverage_50", "width_50", "coverage_90", "width_90")
        ]
        lines.append(f"| {name} | {horizon} | " + " | ".join(cells) + " |")
    label = "Fixture-only selected reference" if fixture else "Reference selected using inner validation only"
    lines += [
        "",
        "## Reference and paired comparisons",
        "",
        f"{label}: **{receipt['selected_reference_by_inner_validation'] or 'NOT ESTABLISHED'}**.",
        f"B0-B2 reference by the same inner rule: {receipt['selected_B0_B2_reference_by_inner_validation']}.",
        "Reference selection uses an unweighted mean of best inner-fold RMSE values, not outer-test labels. "
        "Full real-data G1 evidence is required before naming an empirical strongest baseline.",
        "",
        "| Model | Reference | Horizon | Relative RMSE reduction | 95% CI |",
        "| :--- | :--- | ---: | ---: | :--- |",
    ]
    for item in receipt["paired_comparisons"]:
        if item.get("status") == "Unknown":
            estimate, interval = "Unknown", item["reason"]
        else:
            estimate = f"{item['estimate']:.6g}"
            interval = f"[{item['ci_low']:.6g}, {item['ci_high']:.6g}]"
        lines.append(
            f"| {item['model']} | {item['reference']} | {item['horizon']} | {estimate} | {interval} |"
        )
    lines += [
        "",
        "Intervals use paired race-then-stint bootstrap, keeping original origins within sampled stints.",
        "One-race fixtures cannot supply race-level CIs. Mismatched populations are never intersected.",
        "",
        "## Failures and boundaries",
        "",
    ]
    lines += [f"- {name}: {message}" for name, message in sorted(receipt["failures"].items())] or [
        "None recorded."
    ]
    lines += [
        "",
        "B2 known-variance coverage is tested separately; it is not a real-data calibration result.",
        "B3 capacity is compared with the default M1 network, excluding physical parameters.",
        "Deterministic B0/B2 final members may coincide; their analytic/noise uncertainty remains explicit.",
        "G0 coverage, O1/O2 validation and held-out clipping limits remain open for validation runs.",
        "No physics-model result, pivot or temporal-holdout evaluation is implied by this report.",
        "",
    ]
    return "\n".join(lines)
